#!/usr/bin/env python3
"""Exact finite OPTW certificate checker. Python 3.9+, standard library only.

The compressed payload contains raw decimal instances, untrusted finite covers,
route witnesses and transcribed historical table entries. No network or other
files are used. All scientific arithmetic is integer or Fraction arithmetic.
The cover rule and incident-edge bound are proved in note.tex.
"""
import argparse
import base64
import bisect
import functools
import hashlib
import json
import math
import os
import zlib
from fractions import Fraction


def require(condition, message):
    if not condition:
        raise ValueError(message)


def cents(s):
    q = Fraction(s) * 100
    require(q.denominator == 1, 'decimal precision')
    return q.numerator


class Model:
    def __init__(self, raw):
        lines = [r.split() for r in raw.splitlines() if r.strip()]
        h = lines[0]
        require(len(h) == 16 and h[:2] == ['20', '1'], 'raw header')
        day, n = int(h[2]), int(h[3]) + 1
        require(0 <= day < 7 and 1 < n <= 256 and len(lines) == n+1, 'dimensions')
        self.n = n
        self.x, self.y, self.s, self.p, self.o, self.c = ([] for _ in range(6))
        for i, r in enumerate(lines[1:]):
            require(len(r) == (21 if i else 7) and int(r[0]) == i, 'raw row')
            self.x.append(cents(r[1])); self.y.append(cents(r[2]))
            self.s.append(cents(r[3])); self.p.append(int(r[4]))
            self.o.append(cents(r[6+2*day if i else 5]))
            self.c.append(cents(r[7+2*day if i else 6]))
            require(self.s[i] >= 0 and self.p[i] >= 0 and
                    0 <= self.o[i] <= self.c[i], 'resources')
        require(self.s[0] == self.p[0] == 0, 'depot')
        self.d = [[math.isqrt((a-c)**2+(b-e)**2)
                   for c, e in zip(self.x, self.y)]
                  for a, b in zip(self.x, self.y)]
        self.sp = [r[:] for r in self.d]
        for k in range(n):
            sk = self.sp[k]
            for row in self.sp:
                ik = row[k]
                for j, kj in enumerate(sk):
                    if ik+kj < row[j]:
                        row[j] = ik+kj
        self.mn = [min(row[:i]+row[i+1:]) for i, row in enumerate(self.d)]
        self.w = [2*(s+m) for s, m in zip(self.s, self.mn)]
        # 0/1 knapsack indexed by reward, then minimum weight for AT LEAST r.
        total = sum(self.p)
        inf = sum(self.w)+1
        cost = [0]+[inf]*total
        reached = 0
        for j in range(1, n):
            pj, wj = self.p[j], self.w[j]
            for r in range(reached, -1, -1):
                v = cost[r]+wj
                if v < cost[r+pj]:
                    cost[r+pj] = v
            reached += pj
        for r in range(total-1, -1, -1):
            cost[r] = min(cost[r], cost[r+1])
        self.cost = cost
        def ratio(a, b):
            wa, wb = self.w[a], self.w[b]
            if wa == 0 or wb == 0:
                return (wa != 0)-(wb != 0)
            z = self.p[b]*wa-self.p[a]*wb
            return (z > 0)-(z < 0) or ((a > b)-(a < b))
        self.order = sorted(range(1, n), key=functools.cmp_to_key(ratio))

    def upper(self, i, t, p, memory, U):
        if t+self.sp[i][0] > self.c[0]:
            return True
        cap = 2*(self.c[0]-t)-self.mn[i]-self.mn[0]
        if cap < 0:
            return p <= U
        if p+bisect.bisect_right(self.cost, cap)-1 <= U:
            return True
        val = p
        for j in self.order:
            if memory & (1 << j):
                continue
            start = max(t+self.sp[i][j], self.o[j])
            if start > self.c[j] or start+self.s[j]+self.sp[j][0] > self.c[0]:
                continue
            w = self.w[j]
            if w <= cap:
                cap -= w
                val += self.p[j]
            else:
                val += self.p[j]*cap//w
                break
        return val <= U

    def route(self, r, unrounded=False, schedule=None):
        require(len(r) >= 2 and r[0] == r[-1] == 0 and
                0 not in r[1:-1] and len(set(r[1:-1])) == len(r)-2, 'route')
        require(all(0 <= j < self.n for j in r), 'route indices')
        # Units remain hundredths. Irrational edges get rational upper bounds.
        D = 10**14
        def travel(i, j):
            if not unrounded:
                return self.d[i][j]
            q = ((self.x[i]-self.x[j])**2+(self.y[i]-self.y[j])**2)*D**2
            lo = math.isqrt(q)
            return Fraction(lo+(lo*lo != q), D)
        t, score, completion_late = self.o[0], 0, False
        for i, j in zip(r, r[1:]):
            start = max(t+travel(i,j), self.o[j])
            require(start <= self.c[j], 'service-start deadline')
            t = start+self.s[j]
            if schedule is not None:
                schedule.append({'vertex': j, 'start_hundredths': start,
                                 'finish_hundredths': t,
                                 'closing_hundredths': self.c[j]})
            completion_late |= t > self.c[j]
            require(t+travel(j,0) <= self.c[0], 'direct return')
            score += self.p[j]
        require(t <= self.c[0], 'depot deadline')
        return score, completion_late


def parse_cover(m, proof):
    it = iter(proof.split())
    magic = next(it); n = int(next(it)); P = int(next(it))
    require(magic in ('NGCERT1','NGBOUND2'), 'cover format')
    U = int(next(it)) if magic == 'NGBOUND2' else P
    require(n == m.n and 0 <= P <= U, 'cover header')
    ng = []
    for i in range(n):
        k = int(next(it)); js = [int(next(it)) for _ in range(k)]
        require(0 < k < 63 and len(set(js)) == k and i in js and
                all(0 <= j < n for j in js), 'neighborhood')
        ng.append(js)
    count = int(next(it)); require(0 <= count < 10000000, 'cover length')
    states = []
    for _ in range(count):
        v, t, p, local = [int(next(it)) for _ in range(4)]
        require(0 <= v < n and m.o[0] <= t <= m.c[0] and p >= 0, 'label')
        require(0 <= local < (1 << len(ng[v])) and
                local & (1 << ng[v].index(v)), 'label memory')
        memory = sum(1 << j for a,j in enumerate(ng[v]) if local & (1 << a))
        states.append((v,t,p,memory))
    k = int(next(it)); require(2 <= k <= n+1, 'primal length')
    r = [int(next(it)) for _ in range(k)]
    require(next(it, None) is None, 'trailing cover data')
    require(m.route(r)[0] == P, 'certificate primal')
    return U, P, ng, states


def verify_cover(m, parsed):
    U, P, ng, states = parsed
    at = [[] for _ in range(m.n)]
    for v,t,p,mask in states:
        at[v].append((t,p,mask))
    for a in at:
        a.sort()
    ngmask = [sum(1 << j for j in ns) for ns in ng]
    def covered(v,t,p,mask):
        if m.upper(v,t,p,mask,U):
            return True
        for ct,cp,cm in at[v]:
            if ct > t:
                break
            if cp >= p and cm & mask == cm:
                return True
        return False
    require(covered(0,m.o[0],0,1), 'uncovered root')
    arcs = 0
    for v,t,p,mask in states:
        if t+m.d[v][0] <= m.c[0]:
            require(p <= U, 'false terminal upper')
        for j in range(1,m.n):
            if mask & (1 << j):
                continue
            start = max(t+m.d[v][j],m.o[j])
            tj = start+m.s[j]
            if start > m.c[j] or tj+m.sp[j][0] > m.c[0]:
                continue
            mm = (mask & ngmask[j]) | (1 << j)
            require(covered(j,tj,p+m.p[j],mm), 'uncovered successor')
            arcs += 1
    return len(states), arcs


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--manifest', metavar='PATH',
                        help='write readable evidence after successful verification')
    args = parser.parse_args()
    if hasattr(os, 'nice'):
        os.nice(10)
    data = json.loads(zlib.decompress(base64.b85decode(PAYLOAD)))
    totals = [0,0]; late = 0; above = []; previous = 0; comparison = []
    manifest = []; completion_feasible = []
    require(len(FULL_BENCHMARK) == 33 and len(set(FULL_BENCHMARK)) == 33, "full set")
    for row in data:
        raw, proof = row['raw'], row['proof']
        for field in ('raw','proof'):
            require(hashlib.sha256(row[field].encode()).hexdigest() == row[field+'_sha256'], 'input digest')
        m = Model(raw)
        U,P,ng,states = parse_cover(m,proof)
        require(U == P == row['optimum'], 'matching bound')
        labels, arcs = verify_cover(m,(U,P,ng,states))
        schedule = []
        floor_score, completion_late = m.route(row['route'], schedule=schedule)
        require(floor_score == U, 'floor witness')
        if not completion_late:
            completion_feasible.append(row['name'])
        if row['name'] == 't203':
            customer17 = next(step for step in schedule if step['vertex'] == 17)
            require(customer17 == {'vertex': 17, 'start_hundredths': 100778,
                                  'finish_hundredths': 105178,
                                  'closing_hundredths': 102000}, 't203 schedule')
        require(m.route(row['unrounded_route'],True)[0] == U, 'Euclidean witness')
        late += completion_late
        if 'insertion_route' in row:
            require(m.route(row['insertion_route'])[0] == U, 'stored comparison witness')
            comparison.append(row['name'])
        totals[0] += labels; totals[1] += arcs
        bks, neural = row['bks'], max(row['neural_columns'])
        if U > max(bks,neural):
            above.append(row['name'])
        previous += U in [bks]+row['neural_columns']
        neural_names = ['B.7 global+ft', 'B.1 model', 'B.1 model+as']
        require(len(row['neural_columns']) in (1, 3), 'neural columns')
        evidence = {
            'name': row['name'], 'optimum': U, 'paper_bks': bks,
            'paper_neural_columns': dict(zip(neural_names, row['neural_columns'])),
            'raw_sha256': row['raw_sha256'], 'cover_sha256': row['proof_sha256'],
            'labels': labels, 'permitted_extensions': arcs,
            'truncated_route': row['route'], 'unrounded_route': row['unrounded_route'],
            'truncated_completes_by_close': not completion_late,
            'truncated_schedule_hundredths': schedule,
        }
        if 'insertion_route' in row:
            evidence['stored_comparison_route'] = row['insertion_route']
        manifest.append(evidence)
        print('%s BKS=%d paper-neural=%d optimum=%d labels=%d successors=%d' %
              (row['name'],bks,neural,U,labels,arcs),flush=True)
    require(len(data) == 15 and totals == [225910,11439464], 'total counts')
    require(comparison == ['t202','t208','t218','t227'], 'comparison optima')
    require(completion_feasible == ['t201','t202','t204','t207','t208'],
            'completion-window instances')
    require(late == 10 and previous == 11 and above == ['t203','t204','t236','t243'], 'table consequences')
    print('PASS: 15 exact floor and unrounded optima; labels=%d successors=%d' % tuple(totals))
    print('Stored comparison optimum witnesses: '+','.join(comparison))
    print('Completion-window failures=%d; values already in paper=%d; above paper=%s' %
          (late,previous,','.join(above)))
    if args.manifest:
        with open(args.manifest, 'w', encoding='utf-8') as stream:
            json.dump({'hash_scope': 'Embedded inputs only; no external authentication.',
                       'pagination': 'arXiv:2011.03647v2',
                       'instances': manifest}, stream, indent=2)
            stream.write('\n')
        print('Manifest: '+args.manifest)


